-- Run AFTER schema.sql. Loads the 50 starter products and 2 coupons. Safe to re-run (updates in place).

on conflict (id) do update set name=excluded.name, brand=excluded.brand, category=excluded.category, img=excluded.img,
  price=excluded.price, old_price=excluded.old_price, discount=excluded.discount, description=excluded.description,
  fabric=excluded.fabric, fit=excluded.fit, care=excluded.care, sizes=excluded.sizes, stock=excluded.stock;

on conflict (code) do update set type=excluded.type, value=excluded.value, max=excluded.max, min=excluded.min, label=excluded.label;
